===V11 contacts===
-- A contact is a person at a client: a name, an email and their role. IDENTITY id so the app
-- generates ids on create, while the test seed inserts explicit ids (GENERATED BY DEFAULT lets a
-- supplied id win). client_id is a FK to clients so a contact always points at a real client.
-- The role column is named contact_role to steer clear of any reserved-word ambiguity.
CREATE TABLE contacts (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name         VARCHAR(255) NOT NULL,
    email        VARCHAR(255) NOT NULL,
    contact_role VARCHAR(255) NOT NULL,
    client_id    BIGINT NOT NULL REFERENCES clients (id)
);
===V12===
-- Every contact must have a PROPER email address. The column was already NOT NULL; this adds the
-- format guard at the data layer so a malformed or blank email can never be persisted, matching the
-- UI (contactForm.slot.tsx) and server (CreateContact.java) checks. Regex: local@domain.tld, no
-- whitespace — the same shape clients use (V2__client_email_format.sql).
ALTER TABLE contacts
    ADD CONSTRAINT contacts_email_format
    CHECK (REGEXP_LIKE(email, '^[^@\s]+@[^@\s]+\.[^@\s]+$'));
===Contact.java===
package net.officefloor.hq.app;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * A contact the user keeps for a client: a name, an email, a role, and the id of the client the
 * contact belongs to. Maps the {@code contacts} table (Flyway V11__contacts.sql); the id is
 * IDENTITY-generated on create. The role maps to the {@code contact_role} column.
 */
@Entity
@Table(name = "contacts")
public class Contact {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private String name;

    @Column(nullable = false)
    private String email;

    @Column(name = "contact_role", nullable = false)
    private String role;

    @Column(name = "client_id", nullable = false)
    private Long clientId;

    protected Contact() {
    }

    public Contact(String name, String email, String role, Long clientId) {
        this.name = name;
        this.email = email;
        this.role = role;
        this.clientId = clientId;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getEmail() {
        return email;
    }

    public String getRole() {
        return role;
    }

    public Long getClientId() {
        return clientId;
    }
}
